cat << 'EOF' >> /tmp/group_analysis.py

# Verify associativity (full check)
print("\nVerifying associativity...")
ok = True
for a in elements:
    for b in elements:
        ab = mul[(a,b)]
        for c in elements:
            bc = mul[(b,c)]
            left = mul[(ab, c)]
            right = mul[(a, bc)]
            if left != right:
                print(f"  FAIL: ({a}*{b})*{c} = {left} != {a}*({b}*{c}) = {right}")
                ok = False
                break
        if not ok: break
    if not ok: break
print(f"Associativity: {'OK' if ok else 'FAIL'}")

# Check inverses
print("\nInverses:")
inv = {}
for a in elements:
    for b in elements:
        if mul[(a,b)] == 'e':
            inv[a] = b
            break
for a in elements:
    print(f"  {a}^-1 = {inv[a]}")
EOF
